sc_cat_item_producer.script:
(function producerScript(current, producer) {
    current.name = producer.name;
    current.e_mail = producer.email;
    current.phonenumber = producer.phonenumber;
    current.location = producer.location;
    current.short_description = producer.short_description;
    current.description = producer.description;
    current.feedback_type = producer.feedback_type;
})(current, producer);
